workers = list(set(p[1] for p in pairs))
cost_map = {(p[0], p[1]): p[2] for p in pairs}
min_cost = float('inf')
for p in permutations(workers, len(tasks)):
    current_cost = 0
    possible = True
    for t, w in zip(tasks, p):
        if (t, w) in cost_map:
            current_cost += cost_map[(t, w)]
        else:
            possible = False
            break
    if possible and current_cost < min_cost:
        min_cost = current_cost
result = int(min_cost)

