from itertools import permutations
sheet = 'W1::Allowed assignments'
rows = cells(sheet, 'L812:N820')
costs = {(r[0], r[1]): r[2] for r in rows}
tasks = ['Inspect', 'Pack', 'Polish']
workers = list({r[1] for r in rows})
min_total = None
for p in permutations(workers, 3):
    if all((tasks[i], p[i]) in costs for i in range(3)):
        c = sum(costs[(tasks[i], p[i])] for i in range(3))
        if min_total is None or c < min_total:
            min_total = c
result = min_total

